'use strict';
/**
 * Counties and districts for the USSD channel: the SAME data the mobile app uses
 * (src/constants/liberiaGeographicData.ts, generated by scripts/generate_geo_data.js).
 * The TypeScript file is parsed rather than copied, so the two can never drift apart.
 */
const fs = require('node:fs');
const path = require('node:path');

const SOURCE = path.resolve(__dirname, '../../src/constants/liberiaGeographicData.ts');
let cache = null;

function load() {
  if (cache) return cache;
  const text = fs.readFileSync(SOURCE, 'utf8');
  const grab = (name) => {
    const m = text.match(new RegExp(`export const ${name}: \\w+\\[\\] = (\\[[\\s\\S]*?\\]);`));
    if (!m) throw new Error(`Could not read ${name} from liberiaGeographicData.ts`);
    return JSON.parse(m[1]);
  };
  const counties = grab('COUNTIES');
  const districts = grab('DISTRICTS');
  cache = { counties, districts };
  return cache;
}

const key = (s) => String(s || '').trim().toLowerCase();

function getCountyRecord(name) {
  return load().counties.find((c) => key(c.name) === key(name)) || null;
}

/** Districts of a county, in the same order the app lists them. */
function getDistricts(countyName) {
  const county = getCountyRecord(countyName);
  if (!county) return [];
  return load().districts.filter((d) => d.county_id === county.id);
}

module.exports = { getCountyRecord, getDistricts };
